pre.unscheduledCalendarItems:
function unscheduledCalendarItems(){
  const stageOrder={editing:0,queue:1,scheduled:2,ideas:3};

  const entryItems=state.calendarEntries
    .filter(entry=>!entry.date&&entry.status!=="cancelado")
    .map(entry=>({
      sourceType:"entry",
      sourceId:entry.id,
      title:entry.title,
      lineId:entry.lineId||"",
      meta:entry.origin==="linha"?"Slot de linha editorial":"Planejamento",
      sort:entry.origin==="linha"?0:1,
      targetMonth:entry.targetMonth
    }));

  const postItems=allPosts()
    .filter(post=>{
      const item=state.items?.[post.id];
      return item&&!item.date&&item.stage!=="published";
    })
    .map(post=>{
      const item=state.items[post.id];
      return{
        sourceType:"post",
        sourceId:post.id,
        title:post.title,
        lineId:item.lineId||"",
        meta:STAGE_LABELS[item.stage],
        sort:stageOrder[item.stage]??4,
        targetMonth:null
      };
    });

  return[...entryItems,...postItems].sort((a,b)=>{
    if(a.sourceType!==b.sourceType){
      return a.sourceType==="entry"?-1:1;
    }
    if(
      a.sourceType==="entry"
      &&a.targetMonth!==null
      &&b.targetMonth!==null
      &&a.targetMonth!==b.targetMonth
    ){
      return a.targetMonth-b.targetMonth;
    }
    return a.sort-b.sort||a.title.localeCompare(b.title);
  });
}

pre.renderCalendarProgress:
function renderCalendarProgress(){
  const year=Number(state.settings.calendarYear||2026);
  const capacity=Number(state.settings.weeklyCapacity||3);
  document.getElementById("capacityLabel").textContent=capacity;

  const start=year===2026?dateFromIso(state.settings.planningStart):new Date(year,0,1,12);
  const end=new Date(year,11,31,12);
  const weekKeys=[];
  const seen=new Set();

  for(let date=new Date(start);date<=end;date.setDate(date.getDate()+1)){
    const key=weekKey(date);
    if(!seen.has(key)){seen.add(key);weekKeys.push(key)}
  }

  let filled=0;
  weekKeys.forEach(key=>{
    const postUsed=allPosts().filter(post=>{
      const item=state.items[post.id];
      return item.date&&weekKey(item.date)===key&&item.behavior!=="parallel";
    }).length;
    const entryUsed=state.calendarEntries.filter(entry=>{
      return entry.date&&weekKey(entry.date)===key&&entry.behavior!=="parallel"&&entry.status!=="cancelado";
    }).length;
    filled+=Math.min(postUsed+entryUsed,capacity);
  });

  const total=weekKeys.length*capacity;
  const percent=total?Math.min(100,Math.round((filled/total)*100)):0;
  document.getElementById("progressSlots").textContent=`${filled} de ${total} slots preenchidos`;
  document.getElementById("progressPercent").textContent=`${percent}%`;
  document.getElementById("progressFill").style.width=`${percent}%`;
}
